package com.portfolio.agent.answer.intelligence.retrieval;
import java.util.Optional;
public final class RetrievalFallbackPolicy { public Optional<EffectiveRetrievalPlan> fallbackFor(EffectiveRetrievalPlan plan,RetrievalAttemptFailure failure){if(failure==RetrievalAttemptFailure.VECTOR_UNAVAILABLE&&plan.getPrimaryStrategy()==SearchStrategy.HYBRID)return Optional.of(new EffectiveRetrievalPlan(plan.getIntent(),plan.getPrimaryBackend(),SearchStrategy.KEYWORD,null,null,plan.getExpectedContentVersion()));if((failure==RetrievalAttemptFailure.BACKEND_CONNECTION_UNAVAILABLE||failure==RetrievalAttemptFailure.BACKEND_TIMEOUT)&&plan.getFallbackBackend().isPresent())return Optional.of(new EffectiveRetrievalPlan(plan.getIntent(),plan.getFallbackBackend().get(),plan.getFallbackStrategy().orElse(plan.getPrimaryStrategy()),null,null,plan.getExpectedContentVersion()));return Optional.empty();} }
